const MOUNT = '.claudinite' + '/shared';
const re = new RegExp(String.raw`(?:\bsed\b[^\n]{0,60}?\s-i|\btee\b|\brm\b|\btruncate\b|>>?)[^\n&;|]*\.claudinite\/shared(?:\/|\b)`);

