  ['<placeholder> in heredoc data', `python3 - <<'EOF'\nold="\`${MOUNT}/packs/<id>/pack.mjs\`, falling back"\nEOF`],
  ['plain read', `grep -rn foo ${MOUNT}/packs`],
  ['a real shell write', `sed -i s/a/b/ ${MOUNT}/packs/basics/RULES.md`],
];

for (const [name, cmd] of cases) {
  const m = re.exec(cmd);
